def __find_main_volume_view_dialog_window():
    """Searches for the main VolumeView Preset Selection window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the volume_view_preset_functions.py file

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewPresetObjects.main_Volume_View_Window) is not None else False

def __find_volume_view_inhibits_dialog_window():
    """Searches for the main VolumeView Inhibits window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the volume_view_preset_functions.py file

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewPresetObjects.volume_View_Inhibits_Window) is not None else False

def __locate_textfield_per_pane_by_index_and_id(childObjIndex: int, textfieldId: str) -> object:
    """Searches VolumeView pane child objects based on the positional index and finds the textfield within
    the list of child objects based on the id. Returns object if successfully located. Assumes that the
    ordering of the child objects remains constant.

    Used for textfields that don't have a unique object property, but can be identified by drilling down
    the VolumeView object tree and narrowing the search within a specific pane. The textfield IDs are
    not unique in the main window but typically are within a specific pane.

    :param int childObjIndex: Index of the WindowsControl child object in the first level down to be searched
    :param str textfieldId: Textfield ID text string to be found
    :return: found object
    :rtype: object
    """
    if __find_main_volume_view_dialog_window():
        volume_view_obj_list = CommonActions.get_child_objects(VolumeViewPresetObjects.main_Volume_View_Window)

        if len(volume_view_obj_list) > 0:
            pane_obj_list = volume_view_obj_list[childObjIndex]

            child_pane_obj_list = CommonActions.get_child_objects(pane_obj_list)
            if len(child_pane_obj_list) > 0:
                textfield_object = CommonActions.get_child_object_by_object_id(child_pane_obj_list, textfieldId)
                return textfield_object

@deco.set_separate_app_context(application_name=XVI_APP_NAME)
def wait_for_main_volume_view_window(wait_timeout: int) -> bool:
    """Waits for the main VolumeView Preset Selection window to exist. Returns True if successfully located.
    """
    return True if CommonActions.wait_for_object_exists(VolumeViewPresetObjects.main_Volume_View_Window, wait_timeout) is not None else False

