@deco.set_separate_app_context(application_name=XVI_APP_NAME)
def get_volume_view_gantry_angle_set_textfield() -> str:
    """Locates the main VolumeView Preset Selection window > then reads the data in the Gantry Angle SET textfield only if the object exists
    """
    GANTRY_ANGLE_OBJ_IDX = 16 # Gantry Angle SET and ACTUAL textfields parent windows control object is index no. 16 in the list of VolumeView child objects
    GANTRY_ANGLE_SET_ID = "18005"
    volume_view_gantry_angle_set_textfield = __locate_textfield_per_pane_by_index_and_id(childObjIndex=GANTRY_ANGLE_OBJ_IDX, textfieldId=GANTRY_ANGLE_SET_ID)
    text_value = CommonActions.get_uneditable_field_objects_text_value(volume_view_gantry_angle_set_textfield)
    if text_value is not None:
        return text_value.strip()
    return ""

